// InvoiceScopeTenant restricts a query to a single tenant by adding:
//
//	WHERE inv.organization_id = ? AND inv.business_unit_id = ?
//
// Returns the same *bun.SelectQuery so it can be chained fluently:
//
//	invoicecol.InvoiceScopeTenant(sq, ti).
//		Where(invoicecol.InvoiceColumns.ID.Eq(), id)
func InvoiceScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return buncolgen.ScopeTenant(q, InvoiceColumns.OrganizationID, InvoiceColumns.BusinessUnitID, ti)
}

// InvoiceScopeTenantUpdate restricts an update query to a single tenant.
// Use this inside UpdateQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(uq *bun.UpdateQuery) *bun.UpdateQuery {
//		return invoicecol.InvoiceScopeTenantUpdate(uq, req.TenantInfo).
//			Where(invoicecol.InvoiceColumns.ID.In(), bun.List(ids))
//	})
func InvoiceScopeTenantUpdate(q *bun.UpdateQuery, ti pagination.TenantInfo) *bun.UpdateQuery {
	return buncolgen.ScopeTenantUpdate(q, InvoiceColumns.OrganizationID, InvoiceColumns.BusinessUnitID, ti)
}

// InvoiceScopeTenantDelete restricts a delete query to a single tenant.
// Use this inside DeleteQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(dq *bun.DeleteQuery) *bun.DeleteQuery {
//		return invoicecol.InvoiceScopeTenantDelete(dq, req.TenantInfo).
//			Where(invoicecol.InvoiceColumns.ID.Eq(), id)
//	})
func InvoiceScopeTenantDelete(q *bun.DeleteQuery, ti pagination.TenantInfo) *bun.DeleteQuery {
	return buncolgen.ScopeTenantDelete(q, InvoiceColumns.OrganizationID, InvoiceColumns.BusinessUnitID, ti)
}

// InvoiceApplyTenant returns a closure for SelectQuery.Apply() that scopes to a single tenant.
// Use this instead of wrapping ScopeTenant in an anonymous function:
//
//	q.Apply(invoicecol.InvoiceApplyTenant(tenantInfo))
func InvoiceApplyTenant(ti pagination.TenantInfo) func(*bun.SelectQuery) *bun.SelectQuery {
	return buncolgen.ApplyTenant(InvoiceColumns.OrganizationID, InvoiceColumns.BusinessUnitID, ti)
}

